#!/usr/bin/env node
// Generates server/src/generated/skill-manifest.ts from skill/**.
//
// edgespark deploy runs its own bundler and no npm build hook, so the manifest must be
// COMMITTED (a gitignored generated file would be absent at bundle time). Drift is
// guarded by skill-manifest.sync test, which re-derives this and asserts equality.
//
// Run after editing anything under skill/ or bumping skill/VERSION:
//   node server/scripts/gen-skill-manifest.mjs

import { createHash } from "node:crypto";
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..", "..");
const skillRoot = join(repoRoot, "skill");
const outFile = join(repoRoot, "server", "src", "generated", "skill-manifest.ts");

/** Skill files an agent should be able to fetch. Excludes *.example and any config. */
function collectFiles(dir) {
  const out = [];
  for (const entry of readdirSync(dir).sort()) {
    const abs = join(dir, entry);
    if (statSync(abs).isDirectory()) {
      out.push(...collectFiles(abs));
      continue;
    }
    if (!entry.endsWith(".md")) continue; // SKILL.md + references/*.md only
    out.push(abs);
  }
  return out;
}

const version = readFileSync(join(skillRoot, "VERSION"), "utf8").trim();
const files = collectFiles(skillRoot)
  .map((abs) => {
    const content = readFileSync(abs, "utf8");
    return {
      path: relative(skillRoot, abs).split("\\").join("/"),
      sha256: createHash("sha256").update(content, "utf8").digest("hex"),
      bytes: Buffer.byteLength(content, "utf8"),
      content,
    };
  })
  .sort((a, b) => a.path.localeCompare(b.path));

const banner =
  "// AUTO-GENERATED by server/scripts/gen-skill-manifest.mjs — do not edit by hand.\n" +
  "// Regenerate after any change under skill/ (the skill-manifest.sync test enforces this).\n";

const body =
  `export interface SkillManifestFile {\n` +
  `  readonly path: string;\n` +
  `  readonly sha256: string;\n` +
  `  readonly bytes: number;\n` +
  `  readonly content: string;\n` +
  `}\n\n` +
  `export interface SkillManifest {\n` +
  `  readonly version: string;\n` +
  `  readonly files: readonly SkillManifestFile[];\n` +
  `}\n\n` +
  `export const SKILL_MANIFEST: SkillManifest = ${JSON.stringify({ version, files }, null, 2)} as const;\n`;

writeFileSync(outFile, banner + "\n" + body, "utf8");
console.log(`wrote ${relative(repoRoot, outFile)} — v${version}, ${files.length} files`);
